{
  "name": "opencode-thinking-signature-guard",
  "version": "0.1.1",
  "description": "OpenCode plugin that removes non-replayable Anthropic thinking blocks (redaction-poisoned / short-signature turns) so sessions stop failing with 400 'Invalid signature in thinking block'.",
  "license": "MIT",
  "author": "isac322 <bh322yoo@gmail.com>",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/isac322/opencode-thinking-signature-guard.git"
  },
  "homepage": "https://github.com/isac322/opencode-thinking-signature-guard#readme",
  "bugs": {
    "url": "https://github.com/isac322/opencode-thinking-signature-guard/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "anthropic",
    "claude",
    "thinking",
    "reasoning",
    "signature",
    "redacted-thinking",
    "invalid-signature",
    "interleaved-thinking"
  ],
  "type": "module",
  "main": "./dist/plugin.js",
  "types": "./dist/plugin.d.ts",
  "exports": {
    ".": {
      "types": "./dist/plugin.d.ts",
      "default": "./dist/plugin.js"
    }
  },
  "files": [
    "dist",
    "README.md"
  ],
  "sideEffects": false,
  "engines": {
    "node": ">=18.17"
  },
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "build": "tsgo -p tsconfig.build.json",
    "typecheck": "tsgo --noEmit",
    "check": "biome check .",
    "test": "bun test-fixture.ts fixtures/redacted-turn && bun test-hook.ts fixtures/redacted-turn",
    "test:fixture": "bun test-fixture.ts",
    "test:hook": "bun test-hook.ts",
    "prepublishOnly": "bun run typecheck && bun run check && bun run test && bun run build"
  },
  "devDependencies": {
    "@biomejs/biome": "^2.4.16",
    "@opencode-ai/plugin": "^1.15.12",
    "@types/bun": "^1.3.14",
    "@types/node": "^25.9.1",
    "@typescript/native-preview": "^7.0.0-dev.20260527.2"
  }
}
